STYLE CODE REF:
.cover{
min-height:88vh;
display:flex;
flex-direction:column;
justify-content:flex-end;
padding:clamp(60px,10vw,100px) clamp(24px,4vw,60px);
position:relative;
overflow:hidden;
}

.cover-prism{
position:absolute;
top:0;
right:0;
width:60%;
height:100%;
z-index:0;
}

.prism-glow{ /* main gradient / }
.prism-glow-hot{ / highlight layer / }
.prism-wine{ / base tone */ }

.cover-inner{
position:relative;
z-index:1;
max-width:820px;
}

.cover-bars{
position:absolute;
bottom:clamp(28px,4vw,48px);
left:clamp(24px,4vw,60px);
display:flex;
flex-direction:column;
gap:4px;
}

.cover-spectrum-word{
font-size:clamp(56px,9vw,120px);
line-height:.88;
}

css:
.territory-grid{
display:grid;
grid-template-columns:repeat(3,1fr);
gap:2px;
}

@media(max-width:768px){
.territory-grid{
grid-template-columns:1fr;
}
}

.territory-card{
padding:24px;
}

.territory-card.selected{
outline:2px solid rgba(247,220,111,.14);
}

LAYOUT CODE REF:
CSS:
.sys-grid{
display:grid;
grid-template-columns:1fr 1fr;
gap:2px;
background:var(--border);
margin-top:20px;
}

.sys-card{
background:var(--card);
padding:24px;
}

.sys-card-label{
font-family:var(--fm);
font-size:9px;
letter-spacing:.15em;
text-transform:uppercase;
color:var(--txt-ghost);
}

.sys-card h4{
font-family:var(--fd);
font-style:italic;
font-size:18px;
color:var(--cream);
}

.sys-card p{
font-family:var(--fb);
font-size:13px;
color:var(--txt-dim);
}

