LAYOUT CODE REF:
.ig-grid{
display:grid;
grid-template-columns:repeat(3,1fr);
gap:16px;
}

.ig-post{
aspect-ratio:1;
border-radius:4px;
overflow:hidden;
position:relative;
display:flex;
flex-direction:column;
justify-content:flex-end;
padding:16px;
}

STYLE CODE REF:
.ig-grid{
display:grid;
grid-template-columns:repeat(3,1fr);
gap:16px;
margin-top:24px;
}

@media(max-width:768px){
.ig-grid{
grid-template-columns:1fr;
}
}

.ig-post{
aspect-ratio:1;
border-radius:4px;
overflow:hidden;
position:relative;
display:flex;
flex-direction:column;
justify-content:flex-end;
padding:16px;
}

.ig-label{
font-size:8px;
letter-spacing:.14em;
text-transform:uppercase;
margin-bottom:4px;
}

.ig-title{
font-size:26px;
line-height:.95;
}

.ig-meta{
font-size:8px;
letter-spacing:.08em;
text-transform:uppercase;
margin-top:6px;
}

.ig-manifesto{
margin-top:24px;
padding:28px;
border-radius:2px;
}

.ig-manifesto-line{
font-size:clamp(18px,2.5vw,28px);
line-height:1.2;
}

.card h3{
font-family:var(--fd);
font-style:italic;
font-size:clamp(17px,2vw,22px);
color:var(--cream);
margin-bottom:8px;
}

.card p{
font-family:var(--fb);
font-size:14px;
line-height:1.65;
color:var(--txt-dim);
}

.rule-block{
background:rgba(255,255,255,.025);
border:1px solid var(--border);
border-radius:2px;
padding:18px 22px;
}

.rule-block h4{
font-family:var(--fd);
font-style:italic;
font-size:16px;
color:var(--cream);
}

.rule-block p{
font-family:var(--fb);
font-size:12px;
line-height:1.8;
color:var(--txt-dim);
}

.eco-layout{
display:grid;
grid-template-columns:1fr 1fr;
gap:24px;
margin-top:20px;
}

@media(max-width:768px){
.eco-layout{
grid-template-columns:1fr;
}
}

.eco-layer{
border:1px solid var(--border);
padding:24px;
border-radius:2px;
}

.eco-layer-label{
font-size:9px;
letter-spacing:.15em;
text-transform:uppercase;
margin-bottom:14px;
display:flex;
align-items:center;
gap:8px;
}

.eco-layer-label::before{
content:'';
width:16px;
height:2px;
display:inline-block;
}

.eco-nodes{
display:flex;
flex-direction:column;
gap:6px;
}

.eco-node{
font-size:13px;
padding:10px 14px;
border-left:2px solid var(--border);
line-height:1.55;
}

.eco-node.primary{
color:var(--cream);
}

